//! Generic caller-supplied eleven-lane diagnostic with caller-supplied step.
//! This binary does not verify 0473 provenance. Only the separately pinned
//! 0473 checked runner validates the retained payload, rows, receipt and fixture.
//! Binary snapshot/geometry modes are quiet for machine comparison.
use std::{env,fs,io::{self,Write}};
use spore_core::{creature_generated_skin_kernel_v1::Lane,creature_skin_grid_geometry_v1::{self as geometry,ArithmeticAdmission},creature_skin_scalar_field_v1 as field,creature_skin_seed_v1,creature_skin_queue_v1::Queue,creature_skin_cube_walk_v1 as cube,native_sse::{self,Policy},native_x87::{Context,Precision,Rounding}};
fn push(out:&mut Vec<u8>,v:u32){out.extend(v.to_le_bytes())}
fn main(){let args:Vec<_>=env::args().collect();if args.len()==2&&matches!(args[1].as_str(),"--help"|"-h"){println!("WARNING: This diagnostic accepts a generic caller-supplied eleven-lane fixture; it does not verify 0473 provenance. Only the pinned 0473 checked runner admits the retained payload, rows, receipt and fixture.
Usage: <fixture.bin> <step> <--probe|--snapshot|--geometry>");return}assert_eq!(args.len(),4,"Use --help for input provenance and usage");let bytes=fs::read(&args[1]).unwrap();assert_eq!(bytes.len(),372);let u:Vec<_>=bytes.chunks_exact(4).map(|x|u32::from_le_bytes(x.try_into().unwrap())).collect();assert_eq!(u[8],11);let f=|i:usize|f32::from_bits(u[i]);let lo=[f(0),f(1),f(2)];let hi=[f(3),f(4),f(5)];let step:f32=args[2].parse().unwrap();assert!(step>0.&&step.is_finite());let threshold=f(7);let lanes:Vec<_>=(0..11).map(|i|{let x=9+i*7;Lane{center:[f(x),f(x+1),f(x+2)],cutoff:f(x+3),scale:f(x+4),coefficient:f(x+5),key:u[x+6]}}).collect();let (g,packed)=geometry::derive_and_pack(&lanes,lo,hi,step,threshold,Policy::Mxcsr1f80,ArithmeticAdmission).unwrap();let aligned=geometry::align_lower(lo,step,Policy::Mxcsr1f80,ArithmeticAdmission).unwrap();let (extent,reciprocal)=native_sse::scoped(Policy::Mxcsr1f80,||{let inv=1f32/step;let mut e=[0.;3];for i in 0..3{let span=(hi[i]-aligned[i])*inv;e[i]=span.ceil()*step;}Ok::<_,spore_core::native_sse::SseError>((e,inv))}).unwrap();let cells=packed.cells();let mut groups=vec![[[0.;3];4];3];for (i,l) in lanes.iter().enumerate(){groups[i/4][i%4]=l.center;}let context=Context{precision:Precision::Bits53,rounding:Rounding::NearestEven};let mut failed=false;let mut log=Vec::new();let mut callback=|p:[f32;3]|{match field::evaluate(p,g.origin,g.scale,threshold,&cells,Policy::Mxcsr1f80,context,field::SnapshotAdmission){Ok(v)=>{log.push([p[0].to_bits(),p[1].to_bits(),p[2].to_bits(),v.value.to_bits()]);v.value},Err(_)=>{failed=true;f32::NAN}}};let seed=creature_skin_seed_v1::seed(extent,aligned,step,reciprocal,&groups,11,Policy::Mxcsr1f80,&mut callback).expect("seed failure or unsupported field");let mut q=Queue::from_seed(seed,256,8193,1024).unwrap();let completed=q.run(&cube::tables(),&cube::face_records(),aligned,step,threshold,0.001,Policy::Mxcsr1f80,256,&mut callback).expect("queue failure, work limit or unsupported field");drop(callback);assert!(!failed&&completed==q.entries.len()&&q.geometry.corner_count<=1024&&q.geometry.position_count<=1024&&q.triangles.len()<=1024&&log.len()<=8192);if args[3]=="--probe"{eprintln!("WARNING: generic caller-supplied fixture; 0473 provenance is verified only by the pinned checked runner");println!("seed={seed:08x} queue={} corner={} positions={} triangles={} field={} step={step} aligned={aligned:?} extent={extent:?}",q.entries.len(),q.geometry.corner_count,q.geometry.position_count,q.triangles.len(),log.len());return}let mut out=Vec::new();if args[3]=="--snapshot"{for v in aligned.into_iter().chain(extent).chain([step,reciprocal,threshold]).chain(g.origin).chain(g.scale){push(&mut out,v.to_bits())}push(&mut out,seed);for i in 0..12{let l=lanes.get(i);for axis in 0..3{push(&mut out,l.map_or(0,|v|v.center[axis].to_bits()))}}for cell in cells{let records=cell.unwrap_or(&[]);push(&mut out,records.len() as u32);for record in records{for axis in 0..6{for lane in record{let v=match axis{0..=2=>lane.center[axis],3=>lane.cutoff,4=>lane.scale,_=>lane.coefficient};push(&mut out,v.to_bits())}}for _ in 0..4{push(&mut out,0)}for lane in record{push(&mut out,lane.key)}}}}else{assert_eq!(args[3],"--geometry");for v in [q.cursor as u32,q.entries.len() as u32,q.geometry.status,q.geometry.corner_count,q.geometry.position_count as u32,q.triangles.len() as u32,log.len() as u32]{push(&mut out,v)}for i in 0..256{let e=q.entries.get(i).copied().unwrap_or_default();for v in [e.packed|((e.faces as u32)<<24),e.known as u32|((e.class as u32)<<8)]{push(&mut out,v)}}for i in 0..0x4000{push(&mut out,q.keys[i]);push(&mut out,q.indices[i])}for r in q.geometry.records.iter().take(1024){for &v in r{push(&mut out,v)}}for i in 0..0x8000{for v in [q.geometry.corner_keys[i],q.geometry.corner_values[i][0],q.geometry.corner_values[i][1]]{push(&mut out,v)}}for i in 0..0x8000{for v in [q.geometry.edge_keys[i][0],q.geometry.edge_keys[i][1],q.geometry.edge_values[i]]{push(&mut out,v)}}for p in &q.geometry.positions{for v in p{push(&mut out,v.to_bits())}}for c in &q.geometry.counts{for &v in c{push(&mut out,v)}}for i in 0..1024{for v in q.triangles.get(i).copied().unwrap_or([0;3]){push(&mut out,v)}}for i in 0..8192{for v in log.get(i).copied().unwrap_or([0;4]){push(&mut out,v)}}}io::stdout().write_all(&out).unwrap();}
